from itertools import permutations


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(out) if any(v != bg for v in row)]
    if not active:
        return out

    groups = []
    start = prev = active[0]
    for r in active[1:]:
        if r != prev + 1:
            groups.append(list(range(start, prev + 1)))
            start = r
        prev = r
    groups.append(list(range(start, prev + 1)))

    def end(row):
        return max((c + 1 for c, v in enumerate(row) if v != bg), default=0)

    # Sparse paired dot motifs use a terminal marker for their unmatched reach.
    colors = {v for row in out for v in row if v != bg}
    if (len(groups) == 2 and len(groups[0]) == len(groups[1]) > 1
            and colors == {0} and bg == 2):
        max_end = max(end(row) for row in out)
        r = min(groups[1], key=lambda i: end(out[i]))
        out[r][max_end - 1] = 1
        return out

    # Match the rows of two multi-row motifs by their shared left-hand prefix,
    # then mark the longer row's added pattern in the shorter row.
    if len(groups) == 2 and len(groups[0]) == len(groups[1]) and len(groups[0]) > 1:
        arows, brows = groups
        best = None
        best_score = -1
        for perm in permutations(brows):
            score = 0
            for a, b in zip(arows, perm):
                n = 0
                while n < w and out[a][n] == out[b][n]:
                    n += 1
                score += n
            if score > best_score:
                best_score, best = score, perm
        changed = False
        for a, b in zip(arows, best):
            ea, eb = end(out[a]), end(out[b])
            if ea < eb:
                short, long = a, b
            elif eb < ea:
                short, long = b, a
            else:
                continue
            for c in range(min(ea, eb), max(ea, eb)):
                if out[short][c] == bg and out[long][c] != bg:
                    out[short][c] = 1
                    changed = True
        if changed:
            return out

    # For independent horizontal lines, extend every shorter line to the
    # greatest rightward extent, using 1 for the added cells.
    max_end = max(end(out[r]) for r in active)
    for r in active:
        e = end(out[r])
        for c in range(e, max_end):
            if out[r][c] == bg:
                out[r][c] = 1
    return out
'''
