from itertools import permutations


def transform(grid):
    out = [row[:] for row in grid]
    w = len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(out) if any(v != bg for v in row)]
    if not active:
        return out

    groups = []
    start = prev = active[0]
    for r in active[1:]:
        if r != prev + 1:
            groups.append(list(range(start, prev + 1)))
            start = r
        prev = r
    groups.append(list(range(start, prev + 1)))

    def row_end(r):
        return max((c + 1 for c, value in enumerate(out[r]) if value != bg), default=0)

    widths = [max(row_end(r) for r in group) for group in groups]
    widest = max(widths)
    source_indices = [i for i, width in enumerate(widths) if width == widest]

    for i, group in enumerate(groups):
        if widths[i] == widest:
            continue
        source_group = groups[source_indices[0]]
        if len(group) == len(source_group):
            best = max(permutations(source_group), key=lambda perm: sum(
                next((c for c in range(w) if out[r][c] != out[s][c]), w)
                for r, s in zip(group, perm)))
        else:
            best = source_group
        # Extend the entire object-level width difference, copying its pattern.
        for offset, r in enumerate(group):
            if offset >= len(best):
                break
            source_row = best[offset]
            for c in range(widths[i], widest):
                if out[r][c] == bg and out[source_row][c] != bg:
                    out[r][c] = 1
    return out
